// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public {
        c = new Roulette{value: 10 ether}();
    }

    function testFuzz_property(uint256 amountUnits, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        uint256 k = bound(amountUnits, 0, 20);
        uint256 amount = k * 1 ether;
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");
        // General rule: a call sending exactly 10 ether must be accepted by C.
        if (amount == 10 ether) {
            assertTrue(ok, "10-ether call must succeed");
        }
    }
}
